INSERT INTO products (id, name, cat, gender, family, notes, descr, image_url, live) VALUES
  ('dewivy-bodymist', 'Dewivy bodymist', 'mist', 'Unisex', '', '', 'Awaken your senses with Dewivy, a floral body mist that captures the crisp, soft-toned magic of dawn. This green-fresh floral fragrance is a love letter to nature, blending watery greens with delicate florals to create a scent that is as refreshing as a deep breath of mountain air. It''s clean, sophisticated, and perfect for those who want to feel revitalized and naturally elegant all day long.', NULL, 1),
  ('exotic-kiss-bodymist', 'Exotic kiss bodymist', 'mist', 'Unisex', '', '', '', NULL, 1),
  ('goldplum-bodymist', 'Goldplum bodymist', 'mist', 'Unisex', '', '', 'Goldplum Body mist is a juicy, mouth-watering fruity perfume made for women who love to smell irresistibly good from morning till night. A delicious blend of berries, vanilla, ripe peaches and creamy sandalwood that feels playful, feminine and addictive. It is fresh, sweet, and long-lasting. A true ladies'' bestseller.', NULL, 1),
  ('macho-bodymist', 'Macho bodymist', 'mist', 'Unisex', '', '', '', NULL, 1),
  ('magicspell-bodymist', 'Magicspell bodymist', 'mist', 'Unisex', '', '', '', NULL, 1),
  ('pheromona-bodymist', 'Pheromona bodymist', 'mist', 'Unisex', '', '', '', NULL, 1),
  ('sisi-bodymist', 'Sisi bodymist', 'mist', 'Unisex', '', '', 'Sisi is your instant splash of happiness. It is a bright, refreshing citrus fragrance mist that keeps you smelling clean, fresh and confident for over 12 hours on the skin. A blend of mandarin, sweet orange, vanilla, magnolia and oud., It is light, sparkling, and addictively fresh.', NULL, 1),
  ('sugar-lips-bodymist', 'Sugar lips bodymist', 'mist', 'Unisex', '', '', 'Sugarlips Body Mist is a body mist that captures the playful essence of a sugar-coated dream. This is a "soft-toned" gourmand at its finest, never heavy, always inviting. Designed for the woman who loves to radiate warmth and sweetness. Sugarlips leaves a delicious trail that is as addictive as your favourite treat.', NULL, 1),
  ('tango-bodymist', 'Tango bodymist', 'mist', 'Unisex', '', '', 'Tango is a unisex appealing woody body mist that captures the soul of a moonlit dance. This is a soft-toned sultry scent, bold enough to be noticed, yet light enough to wear like a second skin. A mildly intense rich blend of sandalwood, vanilla, oud, leather, rum. It''s designed for the individual who moves with confidence and leaves a trail of mystery in their wake.', NULL, 1),
  ('tlc-bodymist', 'TLC bodymist', 'mist', 'Unisex', '', '', '', NULL, 1),
  ('toke-bodymist', 'Toke bodymist', 'mist', 'Unisex', '', '', '', NULL, 1),
  ('body-mist-set-of-11', 'Body mist set of 11', 'mist-set', 'Unisex', '', '', '', NULL, 1),
  ('body-mist-set-of-6', 'Body mist set of 6', 'mist-set', 'Unisex', '', '', '', NULL, 1),
  ('2sexy2resist', '2sexy2resist', 'custom-oil', 'Unisex', '', '', '2SEXY2RESIST is a bold, irresistible fragrance made to turn heads and leave a lasting impression. A strong intense floral fragrance that evokes the strong embrace of love and intimacy, melting into the softness of skin on skin and fresh linen sheets. The fragrance that makes hearts beat faster, manners lost, stops time because the most beautiful moments are ignited once you wear this fragrance. Loved by thousands of women and a major staple for any lady who wants to increase the spark in her relationship. This fragrance is very heavy on benzoin, sandalwood, oud and vanilla.', NULL, 1),
  ('a-million-kisses', 'A million kisses', 'custom-oil', 'Unisex', '', '', 'From tuberose to bubblegum, orchids, aldehydes, lily of the valley, bergamot, and sandalwood—Million Kisses is pure magic in a bottle Expect to leave everyone around you completely consumed and utterly mesmerized. It''s lush, it''s heady, it''s unapologetically YOU. Warning: This is for QUEENS ONLY. Spray lavishly, strut boldly, and watch as random kisses, endless compliments, and unwavering admiration follow you. The dry-down? An undeniable 10/10. This fragrance screams, “I''m here, I''m staying, and I OWN this throne!”', NULL, 1),
  ('after-dark', 'After dark', 'custom-oil', 'Unisex', '', '', 'After Dark is a sweet, woody and a bit minty sensation. This fragrance steals your heart before you know it. A perfect blend of lemon, apple, clarysgae, ambroxan, cedarwood, patchouli, vetiver and vanilla. This luminous fragrance is enveloping. A woody oriental fresh unisex fragrance for people who want to tell unique stories with their smellgame.', NULL, 1),
  ('bad-character', 'Bad character', 'custom-oil', 'Unisex', '', '', 'Bad Character EDP is a sparkling floral fragrance. A blend of Turkish rose, bergamot, ylang-ylang and cedarwood. This zesty floral perfume ignites adventure, love, passion and meant for those days you want your aura to be felt before you''re seen.', NULL, 1),
  ('bgs02', 'BGS02', 'custom-oil', 'Unisex', '', '', 'BGS02 50ML Extrait Perfume is a long-lasting luxury fragrance with a soft floral heart and a warm woody-musky base for an elegant, unforgettable signature scent.', NULL, 1),
  ('boss-babe', 'Boss babe', 'custom-oil', 'Unisex', '', '', 'Boss Babe for Women is a sultry fragrance created for women who are not afraid to embody their feminity. It is sexy, flirty, juicy, succulent while being heavily sophisticated. That type of fragrance that gets you stares, opens conversation, and have every lady in the room, wondering what made you so special. Boss babe is a definite must have. It opens with sweet honey and sparkling citrus, melts into a juicy floral heart of cherry, tuberose, orange blossom and pear, and settles into a warm, addictive base of vanilla, tonka bean, sandalwood, amberwood and white musk.', NULL, 1),
  ('chapter-5', 'Chapter 5', 'custom-oil', 'Unisex', '', '', 'This floral bouquet, composed around May rose and jasmine, features bright citrus top notes. Aldehydes create a unique presence, while the smooth touch of bourbon vanilla yields an incredibly sensual sillage.', NULL, 1),
  ('cleopatra', 'Cleopatra', 'custom-oil', 'Unisex', '', '', 'Cleopatra Secrets is a custom hydro perfume. It blends powdery musk and floral aphrodisiacs into a sensual, long-lasting night perfume that clings beautifully to the skin. It is a stunning fragrance that is overwhelming & irresistible; a true symbol of femininity. It combines the magical essences of passion fruit, fresh flowers and precious woods. The woman who uses is radiant,dreamy and not afraid to embody her sensuality to the core. Non-alcoholic, feminine, and unforgettable. Most women vouch for this fragrance as a constant staple that increases the romance in their relationship due to the heavy dirty florals and pheromone materials in it. How to use: Spray on body and lingerie after a night shower. Best paired with the Bikini Package.', NULL, 1),
  ('dangerous', 'Dangerous', 'custom-oil', 'Unisex', '', '', 'Dangerous is a soft-toned floral masterpiece of tension and release. This Natural Extrait is high concentration luxury in its purest form, designed for the woman who is effortlessly captivating and entirely unforgettable. It is the scent of mystery, a whisper of power that lingers on the skin long after you''ve left the room.', NULL, 1),
  ('dominance', 'Dominance', 'custom-oil', 'Unisex', '', '', 'Dominance is a Leathery Extrait de Parfum for Men. It is a modern, niche luxury fragrance created for confident, sophisticated individuals. Featuring a fresh-leather opening with a bold, refined woody build, this powerful unisex perfume delivers intense performance, strong projection and over 24 hours of long-lasting wear. A best seller fragrance for men of all ages.', NULL, 1),
  ('dynasty', 'Dynasty', 'custom-oil', 'Unisex', '', '', 'Dynasty is a bold, smoky-spicy, zesty custom oil made for men who command attention without saying a word. It has powerful projection, unforgettable silage and an ultra-long-lasting trail that keeps working long after you leave the room. Dynasty smells dominant, feels elite and leaves a legacy. If you do not like to take centre stage, avoid this fragrance because it is an announcer.', NULL, 1),
  ('erotica', 'Erotica', 'custom-oil', 'Unisex', '', '', 'EROTICA is a sensual custom-blend fragrant oil, designed for one thing only. Naughty escapades. This is for when you want to drive down the wild side without any inhibitions. Erotica is made from narcissus dirty florals and juicy pomegranate, labdanum and sandalwood. It screams eat me without leaving any crumbs. Lover gang, grab this.', NULL, 1),
  ('essence-of-love', 'Essence of love', 'custom-oil', 'Unisex', '', '', 'Essence of Love is a soft spicy, aquatic,musky unisex fragrance. The notes are lavender, pineapple, pink pepper, patchouli and leather .this aromatic fresh woody perfume is a mega heart stealer. Ready to steal the show? Turn conversations around? Have everyone including strangers want to snuggle up to you, ready to be extremely desired? Essence of love is strictly made to sweep hearts off their feet. By the time they realize what has happened, they are already helplessly in love with you. This is the fragrance you wear to important events, important locations where you want high quality conversations yet in an unprofessional settings. This fragrance is a game changer for ladies. It is also massively loved by men who want to get yes as an answer.', NULL, 1),
  ('flames', 'Flames', 'custom-oil', 'Unisex', '', '', '', NULL, 1),
  ('good-girl-carolina', 'Good girl carolina', 'custom-oil', 'Unisex', '', '', 'Good Girl Carolina is a sensual ambery floral perfume for women that blends bright jasmine and creamy tuberose with warm and sweet roasted tonka bean. Almond adds softness while cocoa deepens the scent, creating a modern, addictive blend with hints of vanilla and subtle woody warmth.', NULL, 1),
  ('high-voltage', 'High voltage', 'custom-oil', 'Unisex', '', '', 'High Voltage eau de parfum with notes of passionfruit, cherry, orchid, hibiscus, agarwood, musk and amber. This perfume is wild, sexy, addictive and totally irresistible. A pheromone infused perfume that drives people wild with desire, passion and emotions. Long lasting, addictive, the ladies cannot get enough of this perfume. A definite compliment bringer. Perfect for everyday wear, date nights, office wear and very versatile.', NULL, 1),
  ('intenso', 'Intenso', 'custom-oil', 'Unisex', '', '', 'Intenso is a bold yet smooth luxury fragrance crafted for those who love depth, confidence, and lasting impression. Rich, sensual notes blend seamlessly into a long lasting perfume oil that sits beautifully on the skin and evolves all day. It is an all manly Eau De Parfum mixing in woody essences with soft floral- oriental smells that brings out the best of both sides. While the wood based fragrances are mostly reserved for a strong rugged yet passionate outlook, the use of soft flower bases brings out the charm allowing man to connect with both the caring and carefree sides. It is an intense electrifying perfume to freshen up your senses. The top layers of this perfume include the sweet smelling lavender while the heart notes revolt with pear, ambrette and iris. Moving on towards the end, you experience the cedarwood and vetiver. Shop intense, a premium, long-lasting perfume made for statement makers and unforgettable moments.', NULL, 1),
  ('invictus', 'Invictus', 'custom-oil', 'Unisex', '', '', '', NULL, 1),
  ('kemistry', 'Kemistry', 'custom-oil', 'Unisex', '', '', 'Unlock a scent that reacts uniquely to your skin with Kemistry. This soft-toned custom oil isn''t just a fragrance; it''s a personal signature. Formulated to adapt to your body''s natural chemistry, Kemistry creates a bespoke aroma that is impossible to replicate. It''s sophisticated, intimate, and deeply magnetic, designed for those who want to be remembered long after they''ve left the room.', NULL, 1),
  ('kill-me-softly', 'Kill me softly', 'custom-oil', 'Unisex', '', '', 'Kill Me Softly is a powerful unisex fragrance created to leave a lasting impression from the very first spray. Warm, glowing and quietly seductive with florals and juicy sweetness for a trail that turns heads and lingers beautifully. This fragrance is an overdose of juicy sweetness. The most beautiful part is that it lasts over two days.', NULL, 1),
  ('kiss-me-deep', 'Kiss me deep', 'custom-oil', 'Unisex', '', '', 'Kiss Me Deep is an enchanting fruity floral fragrance. This irresistible elixir casts a spell of timeless allure, drawing you into a world of magnetic charm and subtle seduction.', NULL, 1),
  ('lick-me-up', 'Lick me up', 'custom-oil', 'Unisex', '', '', 'Lick me up is a pheromone-infused Hydro Perfume made to tempt and tease. A seductive blend of juicy berries, wildflowers, warm resins, and exotic spices that awakens desire and draws them irresistibly closer. Smell edible. Feel powerful. Add to cart.', NULL, 1),
  ('love-breeze-02', 'Love breeze 02', 'custom-oil', 'Unisex', '', '', '', NULL, 1),
  ('love-spell', 'Love spell', 'custom-oil', 'Unisex', '', '', 'With carefully selected notes that balance freshness, warmth, and sensual depth, Lush Life Fragrance Extract enhances your presence effortlessly, whether for everyday wear or special occasions. Just a small application unveils a long-lasting fragrance experience that evolves gracefully throughout the day. Fragrance Profile: Top Notes: Fresh and vibrant accents that awaken the senses Heart Notes: Soft, floral or aromatic layers that add character Base Notes: Deep, warm undertones for a lasting signature Key Features: Highly concentrated for long-lasting wear Smooth, rich scent with a luxurious finish Suitable for both day and evening use Crafted for individuals who value elegance', NULL, 1),
  ('made-for-romance', 'Made for romance', 'custom-oil', 'Unisex', '', '', 'Made for Romance is a hauntingly romantic scent that is composed using calm aquatic notes. A combo of citrus, blackcurrant, lily, may rose, jasmine, vetiver, orris , peach and raspberry. This fragrance is the bomb. Strictly made for when you want all caution to be thrown to the wind. First it creates an urgency in the brain, then it wraps around you, drawing you into every minute and making you never ever wanting those moments too end. A fragrance that can get your skin sniffed for hundreds of times by anyone near you. The people who understand the power of this fragrance already ensures it never misses in their collection. A must-have. It is Perfect for everyday love stories and intimate moments, this long-lasting women''s perfume delivers a clean, romantic scent trail that feels light, feminine and unforgettable. Shop Made for Romance today and fall into a fresh, elegant fragrance made to be remembered.', NULL, 1),
  ('miz-pheromone', 'Miz pheromone', 'custom-oil', 'Unisex', '', '', 'Some fragrances are worn. Mz Pheromone is experienced. Soft white florals, creamy musk, delicate powder, fresh green notes, and warm sensual woods come together to create a fragrance that feels intimate, confident, and undeniably captivating. Rich cashmeran wraps around tuberose and jasmine, while vanilla, petitgrain, benzoin, and a touch of labdanum leave behind a warm, addictive trail that lingers beautifully on the skin. Mz Pheromone was created for the woman who isn''t afraid to embrace her femininity and sensuality. It is bold, elegant, and unforgettable. Perfect for date nights, anniversaries, romantic evenings, and every moment you want to leave a lasting impression. The projection is beautiful, the longevity is exceptional, and the scent has a way of drawing people closer, making every hug last a little longer and every conversation a little more memorable. Notes: Cashmeran • Tuberose • Jasmine • Vanilla • Benzoin.', NULL, 1),
  ('molecule-05', 'Molecule 05', 'custom-oil', 'Unisex', '', '', '', NULL, 1),
  ('money-bag', 'Money bag', 'custom-oil', 'Unisex', '', '', 'It is unisex, powerful, intriguing and leaves a very rich impression. This isn''t just fragrance it is respect and status in a bottle. Wear this woody-leathery sensation when you want to smell like the money you''ll attract. The trail and projection of moneybag scream wealth only.', NULL, 1),
  ('nutty', 'Nutty', 'custom-oil', 'Unisex', '', '', '', NULL, 1),
  ('osk-limited', 'Osk limited', 'custom-oil', 'Unisex', '', '', 'OSK is beast mode in a bottle. The fragrance that one sniff drives you wild with thoughts, passions and romance. OSK is powerfully seductive. A unisex sensation that makes people only think of keeping you for permanent purposes. A blend of grapefruit, agarwood, sandalwood and musk. This is a steady banger. It does not seat for long on our shelves.', NULL, 1),
  ('sauce-queen', 'Sauce queen', 'custom-oil', 'Unisex', '', '', 'Sauce Queen is a soft, irresistible floral-musky fresh gourmand fragrance designed to spark instant attraction and endless compliments. This long-lasting women''s perfume gently fills the room when you arrive and lingers beautifully long after you leave. The sweetness of this perfume cannot be compared to any thing. You may want to avoid this if getting excess compliments is not your thing.', NULL, 1),
  ('secrets-stilettos', 'Secrets & stilettos', 'custom-oil', 'Unisex', '', '', 'Some fragrances smell beautiful. Secrets & Stilettos leaves people completely intrigued. This chypre floral masterpiece is white floral, warm, spicy, sweet, balsamic, aromatic, earthy, and woody. The richness of ylang-ylang, gardenia, and patchouli melts effortlessly into benzoin, sandalwood, and vanilla, creating a scent that is luxurious, mysterious, and impossible to forget. This is for the woman who knows exactly who she is. The woman who can walk from the boardroom to the bedroom without changing her energy. Every room feels brighter when she walks in because her confidence arrives before she speaks. Secrets & Stilettos doesn''t just earn compliments. It starts conversations. People remember you, wonder what you''re wearing, and somehow can never quite figure it out. That mystery is exactly what makes it unforgettable. Notes: Ylang-Ylang • Gardenia • Patchouli • Benzoin • Petitgrain, Sandalwood • Vanilla.', NULL, 1),
  ('sweet-sin', 'Sweet sin', 'custom-oil', 'Unisex', '', '', 'Sweet Sin is the fresh, clean fragrance everyone wants to stay close to. It is a fresh and modern fragrance for men. It opens with captivating notes of Mediterranean neroli and golden apple, followed by a heart of lavender, fir, and black pepper. The base is composed of vanilla, patchouli, and musk, leaving a memorable and long-lasting impression. An ultra-refreshing unisex scent with airy citrus, soft aquatic notes and a smooth musky-amber finish that feels crisp, classy and irresistibly modern. It''s bougie, and perfect for work, everyday wear and scent layering. Smell fresh. Look polished. Feel unforgettable.', NULL, 1),
  ('under-his-skin', 'Under his skin', 'custom-oil', 'Unisex', '', '', 'Under His Skin is a sweet, intimate fragrance designed to evoke the feeling of bare skin, It offers a soft, lingering scent suitable for daily wear and has moderate longevity. Vibe: Intimate, cozy, and alluring.', NULL, 1),
  ('very-sexy-you', 'Very sexy you', 'custom-oil', 'Unisex', '', '', 'Very Sexy is that chypre floral fragrance you didn''t see coming.This fragrance is chic, feminine and juicy. It is quietly seductive, beautifully soft, this is your natural sexy in a bottle. Perfect for daytime, events, hangouts and for date nights, add a touch of essence of love and have them gush over you all night.', NULL, 1),
  ('assasination-box-1', 'Assasination box 1', 'custom-oil-set', 'Unisex', '', '', '', NULL, 1),
  ('assasination-box-2', 'Assasination box 2', 'custom-oil-set', 'Unisex', '', '', '', NULL, 1),
  ('dr-teals-coconut', 'Dr teals coconut', 'deo', 'Unisex', '', '', 'Experience the perfect harmony of wellness and freshness with Dr Teals Coconut Deodorant. This soft-toned, unisex essential is crafted for those who want high-performance protection without the harsh chemicals. Infused with the soothing essence of coconut and skin-loving minerals, it keeps you feeling dry, confident, and smelling like a coastal getaway. It''s not just a deodorant; it''s a daily ritual of self-care that respects your body''s natural rhythm.', NULL, 1),
  ('dr-teals-elderberry', 'Dr teals Elderberry', 'deo', 'Unisex', '', '', 'Experience the perfect harmony of wellness and freshness with Dr Teals Coconut Deodorant. This soft-toned, unisex essential is crafted for those who want high-performance protection without the harsh chemicals. Infused with the soothing essence of coconut and skin-loving minerals, it keeps you feeling dry, confident, and smelling like a coastal getaway. It''s not just a deodorant; it''s a daily ritual of self-care that respects your body''s natural rhythm.', NULL, 1),
