-- Majestic Roobee — the real catalogue.
--
-- Replaces the demo data migration 0002 seeded (tagged by 0007) with the live
-- product list from the client's catalogue: 188 products across 13 categories,
-- 198 sizes. Source: MajesticRoobee_Product_Catalog.xlsx (August 2026).
--
-- Deliberate choices, all editable in the admin afterwards:
--   * Photos are left empty — they are uploaded from Admin → Catalogue.
--   * Every size opens with the same stock at all three stores; real counts
--     are set per store in Admin → Inventory.
--   * The 90 products the catalogue has no copy for get an empty description
--     rather than invented copy.
--   * Scent family is no longer used, so it is stored empty.
--   * Everything ships live; drafts are a per-product toggle in the admin.

-- 1. Clear the demo records. Only rows tagged seeded=1 by 0007 are touched,
--    so anything the shop created itself survives.
DELETE FROM wishlists WHERE product_id IN (SELECT id FROM products WHERE seeded = 1);
DELETE FROM products WHERE seeded = 1;   -- variants -> stock cascade
DELETE FROM orders WHERE seeded = 1;     -- order_items / order_events cascade
DELETE FROM inquiries WHERE seeded = 1;  -- inquiry_messages cascade
DELETE FROM abandoned_checkouts WHERE seeded = 1;
DELETE FROM promos WHERE seeded = 1;
DELETE FROM campaigns WHERE seeded = 1;

-- 1b. FIRSTTRAIL is not demo data: the lead popup prints that code on screen and
--     /api/leads hands it out, so the row has to exist for the code to work at
--     checkout. Re-created as a real promo, with the demo redemption count reset.
VALUES ('FIRSTTRAIL', 'pct', 10, '10% off first order (lead capture)', 'Storewide', 'Always on', '—', 'Active', 0, 0)
ON CONFLICT(code) DO NOTHING;

-- 1c. The announcement bar advertised QUEEN10, which has just been deleted. Only
--     rewritten while it still carries that demo line, so a message the shop has
--     written itself is never overwritten.
UPDATE settings SET value = json_set(value, '$.announcement',
  'Free Abuja delivery over ₦100,000 · Now serving Abuja, Lagos & Ibadan')
WHERE key = 'site' AND json_extract(value, '$.announcement') LIKE '%QUEEN10%';

-- 2. The real categories. Four of the demo ids carry over because they name the
--    same shelf; the rest are new.
ON CONFLICT(id) DO UPDATE SET label = excluded.label, sort = excluded.sort;

-- 3. 'sensual' and 'package' have no equivalent in the real catalogue. Move any
--    product the shop added under them onto the closest real category first, so
--    the foreign key holds, then retire them.
UPDATE products SET cat = 'extrait' WHERE cat = 'sensual';
UPDATE products SET cat = 'fragrance-set' WHERE cat = 'package';
DELETE FROM categories WHERE id IN ('sensual', 'package');

-- 4. The catalogue — 188 products.
--    Upserts, so re-running against a store that already holds one of these
--    (by slug) refreshes it rather than failing the migration. Where the two
--    disagree the catalogue wins on name and shelf, but never overwrites copy,
--    a photo or a draft flag the shop set itself.
ON CONFLICT(id) DO UPDATE SET name = excluded.name, cat = excluded.cat,
  descr = CASE WHEN excluded.descr <> '' THEN excluded.descr ELSE products.descr END;

-- 5. Sizes and prices — 198 rows.
ON CONFLICT(product_id, size) DO UPDATE SET price_ngn = excluded.price_ngn;

-- 6. Opening stock: 10 of every size at each store, and only where the store
--    has no count yet — a real count already entered in the admin is never
--    overwritten.
